// src/pages/ProductDetail.jsx
import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { Helmet } from "react-helmet-async";
import axios from "axios";
import ReviewForm from "../components/ReviewForm";
import { useCartStore } from "../store/cartStore";

// ✅ Use .env variable (defined in frontend .env file)
const API_URL = import.meta.env.VITE_API_BASE_URL;


const ProductDetail = () => {
  const { id } = useParams(); // expects route: /product/:id
  const navigate = useNavigate();
  const addToCart = useCartStore((s) => s.addToCart);

  const [product, setProduct] = useState(null);
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      setLoading(true);
      setError("");
      try {
        // Fetch product (support both {product} and raw object)
        const productRes = await axios.get(`${API_URL}/api/products/${id}`);
        const productData =
          productRes.data?.product ?? productRes.data ?? null;
        if (!productData) {
          if (!cancelled) setError("Product not found.");
          return;
        }

        // Fetch reviews
        const reviewsRes = await axios.get(`${API_URL}/api/reviews/${id}`);
        const fetchedReviews = Array.isArray(reviewsRes.data)
          ? reviewsRes.data
          : reviewsRes.data?.reviews || [];

        // Average rating [0..5]
        const sum = fetchedReviews.reduce(
          (acc, r) => acc + Number(r?.rating || 0),
          0
        );
        const avg = fetchedReviews.length ? sum / fetchedReviews.length : 0;
        const avgClamped = Math.max(0, Math.min(5, avg));

        if (!cancelled) {
          setProduct({ ...productData, avgRating: avgClamped });
          setReviews(fetchedReviews);
        }
      } catch (e) {
        console.error("❌ Product detail fetch failed:", e);
        if (!cancelled) setError("Failed to load product details.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    // Make sure we’re at top when navigating between products
    window.scrollTo(0, 0);
    load();
    return () => {
      cancelled = true;
    };
  }, [id]);

  const handleReviewAdded = (newReview) => {
    const updated = [newReview, ...reviews];
    setReviews(updated);

    const sum = updated.reduce((acc, r) => acc + Number(r?.rating || 0), 0);
    const avg = updated.length ? sum / updated.length : 0;
    const avgClamped = Math.max(0, Math.min(5, avg));
    setProduct((prev) => (prev ? { ...prev, avgRating: avgClamped } : prev));
  };

  if (loading) return <div className="p-8">Loading...</div>;
  if (error) return <div className="p-8 text-red-600">{error}</div>;
  if (!product) return <div className="p-8">Product not found</div>;

  // Robust image URL handling
  const raw = product.imageUrl || product.image || "";
  const imageSrc = raw.startsWith("http")
    ? raw
    : `${API_URL}${raw.startsWith("/") ? raw : `/${raw}`}`;

  const rounded = Math.round(product.avgRating || 0);
  const stars = "★".repeat(rounded) + "☆".repeat(5 - rounded);

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Helmet>
        <title>{product.name} | E-Commerce Store</title>
        <meta name="description" content={product.description || ""} />
      </Helmet>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <img
          src={imageSrc}
          alt={product.name || "Product"}
          loading="lazy"
          width={400}
          height={300}
          className="w-full rounded-lg object-cover bg-gray-50"
          onError={(e) => {
            e.currentTarget.onerror = null;
            e.currentTarget.src =
              "https://dummyimage.com/400x300/cccccc/000000&text=No+Image";
          }}
        />

        <div>
          <h1 className="text-2xl font-bold">{product.name || "Product"}</h1>
          <p className="text-gray-600 mt-2">
            {product.description || "No description."}
          </p>
          <p className="text-xl font-semibold mt-4">
            PKR {product.price ?? "N/A"}
          </p>

          <div className="flex items-center gap-2 mt-3">
            <span className="text-yellow-500">{stars}</span>
            <span className="text-sm text-gray-600">
              ({reviews.length} reviews)
            </span>
          </div>

          <button
            onClick={() => {
              addToCart?.(product);
              navigate("/cart");
            }}
            className="mt-6 bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700"
          >
            Add to Cart
          </button>
        </div>
      </div>

      <div className="mt-10">
        <h2 className="text-xl font-semibold mb-4">Customer Reviews</h2>

        {reviews.length === 0 ? (
          <p className="text-gray-500">No reviews yet.</p>
        ) : (
          reviews.map((review) => {
            const r = review || {};
            const rating = Math.max(0, Math.min(5, Number(r.rating || 0)));
            const rStars = "★".repeat(rating) + "☆".repeat(5 - rating);

            const rImgRaw = r.imageUrl || "";
            const rImg = rImgRaw
              ? rImgRaw.startsWith("http")
                ? rImgRaw
                : `${API_URL}${rImgRaw.startsWith("/") ? rImgRaw : `/${rImgRaw}`}`
              : "";

            return (
              <div key={r._id || r.id} className="border rounded-lg p-4 mb-4">
                <div className="flex items-center gap-2 mb-1">
                  <strong>{r.user?.name || "User"}</strong>
                  <span className="text-yellow-500">{rStars}</span>
                </div>
                <p className="text-gray-800">{r.comment || ""}</p>

                {rImg && (
                  <img
                    src={rImg}
                    alt="review"
                    loading="lazy"
                    className="mt-2 w-32 rounded-md object-cover bg-gray-50"
                    onError={(e) => {
                      e.currentTarget.onerror = null;
                      e.currentTarget.src =
                        "https://dummyimage.com/100x100/cccccc/000000&text=No+Image";
                    }}
                  />
                )}

                <p className="text-xs text-gray-400 mt-1">
                  {r.createdAt
                    ? new Date(r.createdAt).toLocaleDateString()
                    : ""}
                </p>
              </div>
            );
          })
        )}

        <ReviewForm
          productId={product._id || product.id}
          onReviewAdded={handleReviewAdded}
        />
      </div>
    </div>
  );
};

export default ProductDetail;
